import{_ as c,o as s,c as n}from"./chunks/framework.D4oetGi0.js";const m=JSON.parse('{"title":"Linux 内核问题排查与处理","titleTemplate":":title · 知行笔记","description":"遇到内存异常、系统卡顿、TCP重传或网络吞吐下降时，从这里按现象定位。示例PID 24680 、服务 demo-api 、网卡 eth0 和IP 192.0.2.10 均按实际值替换；采样命令默认只观察，不修改内核参数。 1. 先决定查哪条","frontmatter":{"title":"Linux 内核问题排查与处理","titleTemplate":":title · 知行笔记","description":"遇到内存异常、系统卡顿、TCP重传或网络吞吐下降时，从这里按现象定位。示例PID 24680 、服务 demo-api 、网卡 eth0 和IP 192.0.2.10 均按实际值替换；采样命令默认只观察，不修改内核参数。 1. 先决定查哪条","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"ddd-design-practice\\",\\"title\\":\\"DDD 建模与落地实践\\",\\"module\\":\\"architecture\\",\\"category\\":\\"架构设计\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"category\\":\\"Linux 运维\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">Linux 运维\\\\u003c/div>\\\\u003ch1>Linux 内核问题排查与处理\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 37 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">linux\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">kernel\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">memory\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">page-cache\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">oom\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">tcp\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">troubleshooting\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003cp>遇到内存异常、系统卡顿、TCP重传或网络吞吐下降时，从这里按现象定位。示例PID \\\\u003ccode>24680\\\\u003c/code>、服务 \\\\u003ccode>demo-api\\\\u003c/code>、网卡 \\\\u003ccode>eth0\\\\u003c/code> 和IP \\\\u003ccode>192.0.2.10\\\\u003c/code> 均按实际值替换；采样命令默认只观察，不修改内核参数。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"1-先决定查哪条线\\\\\\">1. 先决定查哪条线\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：按现象选分支 → 记录时间和内核 → 看整机趋势 → 再进入对应章节。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>现象\\\\u003c/th>\\\\n\\\\u003cth>优先检查\\\\u003c/th>\\\\n\\\\u003cth>后续动作\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>load升高、进程卡住\\\\u003c/td>\\\\n\\\\u003ctd>vmstat、D状态、回收和I/O\\\\u003c/td>\\\\n\\\\u003ctd>区分CPU排队、存储等待、内存回收\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>内存越来越少\\\\u003c/td>\\\\n\\\\u003ctd>meminfo、进程RSS/PSS、Shmem、Slab\\\\u003c/td>\\\\n\\\\u003ctd>找到增长的内存类型，再查归属\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>机器有空闲内存，容器却OOM\\\\u003c/td>\\\\n\\\\u003ctd>cgroup限制及事件\\\\u003c/td>\\\\n\\\\u003ctd>查容器边界，而非只查整机\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>短时延迟毛刺、sys CPU升高\\\\u003c/td>\\\\n\\\\u003ctd>回收、规整、THP、热点栈\\\\u003c/td>\\\\n\\\\u003ctd>按毛刺发生时间关联证据\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>新连接超时或排队\\\\u003c/td>\\\\n\\\\u003ctd>SYN队列、accept队列、应用处理能力\\\\u003c/td>\\\\n\\\\u003ctd>查连接阶段与监听队列\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>已连接但传输慢\\\\u003c/td>\\\\n\\\\u003ctd>RTT、重传、收发队列、窗口\\\\u003c/td>\\\\n\\\\u003ctd>查链路及收发两端\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>单核软中断高\\\\u003c/td>\\\\n\\\\u003ctd>网卡队列、中断分布、包速率\\\\u003c/td>\\\\n\\\\u003ctd>查流量分布和CPU余量\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 记录当前时间，方便与业务和系统日志对齐\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">date\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认正在运行的内核版本\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -r\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看运行时长和1、5、15分钟平均负载\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒采样整机运行队列、阻塞、换页、I/O和CPU，共5次\\\\u003c/span>\\\\nvmstat 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看整机可用内存、缓存和Swap占用\\\\u003c/span>\\\\nfree -h\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：load升高且 \\\\u003ccode>vmstat\\\\u003c/code> 的 \\\\u003ccode>b\\\\u003c/code> 增多，就继续查阻塞和I/O；\\\\u003ccode>r\\\\u003c/code>持续高、CPU忙则转查CPU。不要看到load高就直接认定CPU不够。\\\\u003ccode>vmstat\\\\u003c/code>第一行通常包含开机以来的平均值，后续才是间隔采样。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>安装排查工具与确认内核功能\\\\u003c/summary>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>命令\\\\u003c/th>\\\\n\\\\u003cth>Ubuntu / Debian包\\\\u003c/th>\\\\n\\\\u003cth>RHEL系包\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>top、ps、free、vmstat、pmap、slabtop\\\\u003c/td>\\\\n\\\\u003ctd>procps\\\\u003c/td>\\\\n\\\\u003ctd>procps-ng\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>sar、mpstat、pidstat、iostat\\\\u003c/td>\\\\n\\\\u003ctd>sysstat\\\\u003c/td>\\\\n\\\\u003ctd>sysstat\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>ss、ip、nstat\\\\u003c/td>\\\\n\\\\u003ctd>iproute2\\\\u003c/td>\\\\n\\\\u003ctd>iproute\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>findmnt、ipcs、lscpu、taskset、chrt\\\\u003c/td>\\\\n\\\\u003ctd>util-linux\\\\u003c/td>\\\\n\\\\u003ctd>util-linux\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>numactl、numastat\\\\u003c/td>\\\\n\\\\u003ctd>numactl\\\\u003c/td>\\\\n\\\\u003ctd>numactl\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>lsof、strace、tcpdump、ethtool\\\\u003c/td>\\\\n\\\\u003ctd>同名包\\\\u003c/td>\\\\n\\\\u003ctd>同名包\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>perf\\\\u003c/td>\\\\n\\\\u003ctd>Ubuntu为匹配内核的linux-tools，Debian通常为linux-perf\\\\u003c/td>\\\\n\\\\u003ctd>perf\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>trace-cmd\\\\u003c/td>\\\\n\\\\u003ctd>trace-cmd\\\\u003c/td>\\\\n\\\\u003ctd>trace-cmd\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>cat、grep、awk、sort、head、wc、getconf等通常随基础系统提供。journalctl与systemctl属于systemd工具，非systemd环境改查该系统的日志和服务管理方式。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian，按需选包\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 更新软件包索引，会访问当前已配置的软件源\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get update\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian：安装下方列出的排查工具，会修改已安装软件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install sysstat lsof tcpdump iproute2 ethtool numactl strace procps util-linux\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># RHEL系，改选本机对应仓库中的包\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo dnf install sysstat lsof tcpdump iproute ethtool numactl strace perf procps-ng util-linux\\\\u003c/span>\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu：需要perf时安装匹配当前运行内核的工具\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install linux-tools-common \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;linux-tools-\\\\u003cspan class=\\\\\\"hljs-subst\\\\\\">$(uname -r)\\\\u003c/span>&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Debian：需要perf时选择此命令，不重复执行Ubuntu的包名\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install linux-perf\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>sysstat\\\\u003c/code>提供sar、mpstat、pidstat、iostat；Ubuntu的perf通常来自匹配内核的linux-tools包，Debian常见包名为linux-perf，先核对系统和仓库。不要为运行perf安装不匹配的内核工具或修改整机安全限制。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7按现有批准仓库选用：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> yum install sysstat lsof tcpdump iproute ethtool numactl strace procps-ng util-linux \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 安装基础采样工具\\\\u003c/span>\\\\nrpm -q kernel perf          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看已安装内核和perf包版本\\\\u003c/span>\\\\nyum --showduplicates list perf \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询源中perf候选版本，核对与运行内核的匹配情况\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo yum install perf     # 仅在候选版本与运行环境匹配时安装\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -r                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 记录当前运行内核，不能只看已安装内核包\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：CentOS 7常见3.10内核，但包含发行版回移补丁，能力以实际配置和事件为准。仓库失效处理见\\\\u003ca href=\\\\\\"linux-server-operations-commands.html\\\\\\">服务器常用命令\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认这些命令是否已安装及其可执行文件路径\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v sar iostat numactl ethtool perf\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看perf工具版本\\\\u003c/span>\\\\nperf --version\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 列出当前环境可用的性能事件\\\\u003c/span>\\\\nperf list\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：PSI、smaps_rollup、tracepoint、cgroup文件依赖内核版本及配置。文件不存在或权限不足时，先确认功能支持与授权；CentOS 7等旧环境不能照搬新内核路径。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003ch2 id=\\\\\\"2-free很少是否真的缺内存\\\\\\">2. free很少，是否真的缺内存\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看meminfo分类 → 再按RSS找进程 → 用趋势确认增长来源。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取内存分类，区分匿名页、文件缓存、共享内存与Slab\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;^(MemTotal|MemFree|MemAvailable|Cached|Buffers|Active\\\\\\\\(file\\\\\\\\)|Inactive\\\\\\\\(file\\\\\\\\)|AnonPages|Shmem|Slab|SReclaimable|SUnreclaim|Dirty|Writeback|SwapTotal|SwapFree):&#x27;\\\\u003c/span> /proc/meminfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按常驻内存RSS倒序显示进程，含表头最多15行\\\\u003c/span>\\\\nps -eo pid,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">comm\\\\u003c/span>,rss,vsz --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span>=-rss | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 15\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：Cached较大但MemAvailable仍充足、业务正常，不需要“清缓存”。AnonPages增长查进程匿名内存；Shmem增长查共享内存/tmpfs；SUnreclaim增长查内核分配。\\\\u003ccode>| head\\\\u003c/code>只保留前15行输出。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：以可用内存、交换活动、业务延迟及增长趋势判断压力。不能直接把各进程RSS相加当成实际物理占用，共享页会重复计数；meminfo里的不同分类也不应简单相加。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：在同类负载下连续观察，确认MemAvailable不再持续下降、没有回收抖动和OOM。\\\\u003ca href=\\\\\\"https://man7.org/linux/man-pages/man5/proc_meminfo.5.html\\\\\\">字段说明\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"3-load飙高延迟变大检查回收和脏页\\\\\\">3. load飙高、延迟变大：检查回收和脏页\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看sar回收 → 同时看设备延迟和脏页 → 只读现有参数 → 再选处理办法。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒采样缺页和内存回收指标，共5次\\\\u003c/span>\\\\nsar -B 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒采样设备I/O延迟、队列和读写量，共5次；-y跳过首份累计报告\\\\u003c/span>\\\\niostat -xz -y 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看脏页和正在回写的数据量\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;^(Dirty|Writeback):&#x27;\\\\u003c/span> /proc/meminfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取回收、规整和脏页指标；累计项需要比较两次采样增量\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;pgscan|pgsteal|allocstall|compact_stall|nr_dirty|nr_writeback&#x27;\\\\u003c/span> /proc/vmstat\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：sar显示直接回收活动增加，且存储延迟和Dirty/Writeback在同一时间异常，才进一步怀疑回收/回写拖慢应用。\\\\u003ccode>/proc/vmstat\\\\u003c/code>里的许多值是累计计数，应间隔采样看增量，不能凭非零就认定正在故障。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>sar -B字段\\\\u003c/th>\\\\n\\\\u003cth>看什么\\\\u003c/th>\\\\n\\\\u003cth>下一步\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>pgscank/s\\\\u003c/td>\\\\n\\\\u003ctd>后台kswapd每秒扫描页数\\\\u003c/td>\\\\n\\\\u003ctd>结合可用内存判断回收压力\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>pgscand/s\\\\u003c/td>\\\\n\\\\u003ctd>应用分配路径直接扫描页数\\\\u003c/td>\\\\n\\\\u003ctd>若与延迟同步升高，继续追直接回收事件\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>pgsteal/s\\\\u003c/td>\\\\n\\\\u003ctd>每秒实际回收页数\\\\u003c/td>\\\\n\\\\u003ctd>与扫描量一起看，不能单独按大/小判断好坏\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>%vmeff\\\\u003c/td>\\\\n\\\\u003ctd>回收量与扫描量的比值\\\\u003c/td>\\\\n\\\\u003ctd>低值提示扫描收益差，但不是业务是否正常的唯一标准\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>majflt/s\\\\u003c/td>\\\\n\\\\u003ctd>需要I/O等处理的主要缺页\\\\u003c/td>\\\\n\\\\u003ctd>对照读盘、Swap及进程映射\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>示例：pgscand/s从平时接近0变为持续较高，同时P99抖动，说明应用可能在同步参与回收；若扫描很多、回收很少，再查页是否被引用、脏页回写或其他回收限制。字段及计数口径以本机sysstat和内核版本为准。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先减少批处理、突发写入和内存竞争，定位慢存储；有泄漏先处理泄漏。确需调整回收水位或脏页策略时，先记录现值，再按机器内存和存储能力做小范围试验，不直接套固定GB值或比例。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读：查看内存预留水位相关参数\\\\u003c/span>\\\\nsysctl vm.min_free_kbytes vm.watermark_scale_factor\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读：查看按比例配置的脏页后台回写和写入限制\\\\u003c/span>\\\\nsysctl vm.dirty_background_ratio vm.dirty_ratio\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读：查看按字节配置的脏页后台回写和写入限制\\\\u003c/span>\\\\nsysctl vm.dirty_background_bytes vm.dirty_bytes\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这些命令只读取参数；旧内核可能没有其中某项。bytes与ratio控制方式需按内核规则选择，不能把两组值当作互不相关的限制随意同时配置。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：比较相近流量下的直接回收增量、I/O延迟和P95/P99；内存预留增加也会压缩应用可用容量。\\\\u003ca href=\\\\\\"https://docs.kernel.org/admin-guide/sysctl/vm.html\\\\\\">VM参数说明\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"4-清过缓存后更慢检查热点数据反复读盘\\\\\\">4. 清过缓存后更慢：检查热点数据反复读盘\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先确认缺页与读盘增加 → 对照缓存变化 → 查清缓存或竞争任务 → 恢复热点工作集。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒采样缺页和内存回收指标，共5次\\\\u003c/span>\\\\nsar -B 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒观察目标进程的缺页、RSS和虚拟内存，共5次\\\\u003c/span>\\\\npidstat -r -p 24680 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒观察目标进程实际存储读写量，共5次\\\\u003c/span>\\\\npidstat -d -p 24680 1 5\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：延迟升高同时出现主要缺页、读盘增加和缓存下降，要检查是否有人定时执行drop_caches，或其他大扫描挤出了热点缓存。主要缺页增加也可能涉及交换，需结合I/O和映射判断。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：取消无依据的周期清缓存，错开全盘扫描/备份和在线业务；对延迟敏感服务合理预热、隔离竞争和配置内存。不要为了让free数字变大而每天清Page Cache。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看热点页被回收后再次访问的计数线索，采样两次比较增量\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;^workingset_(refault|activate|restore)&#x27;\\\\u003c/span> /proc/vmstat\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读确认是否存在定时清缓存任务；仅查常见系统任务目录，不代表覆盖所有自动化来源\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> grep -Rns \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;drop_caches&#x27;\\\\u003c/span> /etc/cron.d /etc/cron.daily /etc/cron.hourly /etc/crontab\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：refault增量、读盘和业务延迟一起升高，说明热点数据可能被反复挤出；该计数为整机线索，仍要确认具体进程及文件。write成功也不等于数据已经持久化到存储；脏页回写、fsync语义和设备持久性要按应用要求分别核对。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：观察热点请求的读盘量、缺页活动和延迟是否恢复；冷启动与缓存预热后的结果分别记录。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"5-进程rss持续涨区分堆映射与共享页\\\\\\">5. 进程RSS持续涨：区分堆、映射与共享页\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看status分类 → 再看smaps/PSS → 用pmap找增长映射 → 选运行时或分配追踪工具。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取目标进程的匿名、文件、共享常驻页和Swap分类\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;VmRSS|VmSize|RssAnon|RssFile|RssShmem|VmSwap&#x27;\\\\u003c/span> /proc/24680/status\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取目标进程的RSS、PSS与私有/共享页汇总，需要相应权限\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/24680/smaps_rollup\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看目标进程各内存映射的大小与常驻量\\\\u003c/span>\\\\npmap -x 24680\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：匿名常驻页持续增长时继续查堆/匿名映射；文件映射增长时查映射文件及生命周期。smaps_rollup中的PSS按共享比例分摊，更适合辅助判断归属；文件存在与读取权限以系统为准。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7等旧内核没有 \\\\u003ccode>smaps_rollup\\\\u003c/code> 时，读取同一进程的 \\\\u003ccode>smaps\\\\u003c/code> 汇总；先替换PID，并使用有读取权限的身份：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> awk \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;/^Rss:/ {rss+=$2} /^Pss:/ {pss+=$2} END {printf &quot;RSS=%d kB PSS=%d kB\\\\\\\\n&quot;,rss,pss}&#x27;\\\\u003c/span> /proc/24680/smaps \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 汇总映射的RSS与PSS\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：RSS可能重复计算共享页；这些是读取期间的近似快照，不能把两次不同时间的值当作同一个瞬间。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先按应用语言使用堆分析、分配采样或运行时诊断，区分泄漏、缓存、分配器保留和负载增长；为异常服务限制流量并保留现场。生产上不直接启动全量Valgrind或无上限采样。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：在稳定负载和相近运行时长下，检查内存是否趋稳、GC后是否回落，以及错误率和延迟有没有恶化。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"6-rss不高shmem很大查tmpfs与共享内存\\\\\\">6. RSS不高、Shmem很大：查tmpfs与共享内存\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看Shmem → 找tmpfs挂载和占用 → 查共享段及删除后未释放的文件 → 确认创建者。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看整机共享内存/tmpfs相关内存占用\\\\u003c/span>\\\\ngrep \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;^Shmem:&#x27;\\\\u003c/span> /proc/meminfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 列出tmpfs挂载点，确认临时文件存在哪里\\\\u003c/span>\\\\nfindmnt -t tmpfs\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看共享内存和运行目录所在文件系统的容量与类型\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -hT /dev/shm /run\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按一级目录统计占用，-x不跨文件系统，扫描可能产生I/O\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">du\\\\u003c/span> -xhd1 /dev/shm /run\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 列出System V共享内存段\\\\u003c/span>\\\\nipcs -m\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查找已删除但仍被进程打开、尚未释放空间的文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> lsof +L1\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>/run\\\\u003c/code>或 \\\\u003ccode>/dev/shm\\\\u003c/code>占用增长，且Shmem同步增长，即使应用已经关闭文件也可能保留数据；\\\\u003ccode>ipcs -m\\\\u003c/code>查看System V共享内存，不能覆盖所有共享内存类型。已删除但仍打开的文件还会占用空间。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：找到创建者与保留规则，再清理确认无用的临时文件或修复应用生命周期。不要清空 \\\\u003ccode>/run\\\\u003c/code>、盲目 \\\\u003ccode>ipcrm\\\\u003c/code> 或直接删除仍被业务使用的共享文件；tmpfs数据也不等于可随时丢弃。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：文件系统占用与Shmem均回落，并确认服务连接、锁、PID和共享数据仍正常。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"7-内核内存持续增长查slab驱动与分配点\\\\\\">7. 内核内存持续增长：查Slab、驱动与分配点\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先确认内核内存类型 → slabtop找增长对象 → 对照模块和内核日志 → 再深入分配栈。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取内核内存分类，判断哪一类持续增长\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;^(Slab|SReclaimable|SUnreclaim|VmallocUsed|KernelStack|PageTables):&#x27;\\\\u003c/span> /proc/meminfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 输出一份Slab对象和缓存占用快照\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> slabtop -o\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 列出已加载模块，辅助关联驱动或模块变化\\\\u003c/span>\\\\nlsmod\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看本次开机最近100条内核日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b -n 100 --no-pager\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：SUnreclaim持续上升而进程占用相对稳定，记录slab对象类别的变化；必要时让内核/驱动维护人员进一步检查vmallocinfo与分配栈。某个值大并不足以证明泄漏。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：关联近期驱动、模块和内核更新，优先在测试环境复现并升级/回退问题组件；内核态泄漏不会因为重启一个Java进程就必然释放。kmemleak、kprobe等依赖构建选项与诊断成本，不在生产临时随意开启。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：对比相同负载下对象数量、内存增长斜率及错误日志，确认不是暂时缓存下降。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"8-服务被杀容器oom先确认边界\\\\\\">8. 服务被杀、容器OOM：先确认边界\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先查OOM日志 → 确认目标进程及cgroup → 读取真实限制与事件 → 判断整机还是分组不足。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 从本次开机内核日志中筛选OOM和被杀进程记录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b --no-pager | grep -Ei \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;out of memory|oom-kill|killed process&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取目标进程所在的cgroup路径\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/24680/cgroup\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看服务的cgroup路径及systemd配置的内存上限\\\\u003c/span>\\\\nsystemctl show demo-api -p ControlGroup -p MemoryMax\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：整机还有空闲内存，不代表服务没有超出cgroup限额；OOM被杀的进程也不一定是最早引起压力的进程。结合时间、PID、分组和实际限额判断。\\\\u003c/p>\\\\n\\\\u003cp>确认使用cgroup v2、ControlGroup为 \\\\u003ccode>/system.slice/demo-api.service\\\\u003c/code> 后读取：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># cgroup v2：查看此服务当前内存占用，单位为字节\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/system.slice/demo-api.service/memory.current\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># cgroup v2：查看内存硬上限；max表示此层不设上限\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/system.slice/demo-api.service/memory.max\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># cgroup v2：读取达到限制、OOM及杀进程等累计事件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/system.slice/demo-api.service/memory.events\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：关注 \\\\u003ccode>oom/oom_kill\\\\u003c/code>计数是否在事故期间增加，区分达到限额与实际杀进程；这些是累计事件，需结合分组生命周期。cgroup v1用其对应控制器文件，不能硬套v2路径。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7常见cgroup v1。先执行 \\\\u003ccode>cat /proc/24680/cgroup\\\\u003c/code>、\\\\u003ccode>findmnt -t cgroup\\\\u003c/code>，找到memory控制器路径及挂载点。以下假设确认为 \\\\u003ccode>/sys/fs/cgroup/memory/system.slice/demo-api.service\\\\u003c/code>；容器、用户slice和非默认挂载必须改成实际目录：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">systemctl show demo-api -p ControlGroup -p MemoryLimit \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># systemd 219读取旧版限制属性\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/memory/system.slice/demo-api.service/memory.usage_in_bytes \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前分组用量\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/memory/system.slice/demo-api.service/memory.limit_in_bytes \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 分组内存硬上限\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/memory/system.slice/demo-api.service/memory.failcnt \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 累计触及限额的次数\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/fs/cgroup/memory/system.slice/demo-api.service/memory.oom_control \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前OOM相关状态，可用字段随内核变化\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;30 minutes ago&#x27;\\\\u003c/span> --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 结合内核日志确认实际OOM及被杀进程\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>memory.failcnt\\\\u003c/code>增长表示触及限额，不等于杀进程次数；\\\\u003ccode>under_oom=0\\\\u003c/code>也不能证明过去没发生过OOM。比较事故前后增量并查日志，还需检查父分组限制；v1没有v2的 \\\\u003ccode>memory.events\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先减负载、处理泄漏或在容量允许时调整限额；JVM堆外、线程栈、页缓存等也需预留空间。避免给所有业务设置不可被OOM杀死的保护，导致压力转嫁给整机。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：观察同类负载下的memory.current、事件增量和业务状态。\\\\u003ca href=\\\\\\"https://docs.kernel.org/admin-guide/cgroup-v2.html\\\\\\">cgroup v2说明\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"9-有空闲内存还卡顿查numa和透明大页\\\\\\">9. 有空闲内存还卡顿：查NUMA和透明大页\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看NUMA分布 → 查绑核/节点及回收策略 → 对照THP模式和规整增量 → 做有范围的对照。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看NUMA节点、各节点CPU及内存分布\\\\u003c/span>\\\\nnumactl --hardware\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看目标进程的NUMA内存分布\\\\u003c/span>\\\\nnumastat -p 24680\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读：查看NUMA本地内存回收策略\\\\u003c/span>\\\\nsysctl vm.zone_reclaim_mode\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看透明大页启用策略，方括号中的值为当前模式\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/kernel/mm/transparent_hugepage/enabled\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看透明大页内存规整策略\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /sys/kernel/mm/transparent_hugepage/defrag\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看内存规整和透明大页指标，累计项需比较增量\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;compact_stall|compact_fail|compact_success|thp_&#x27;\\\\u003c/span> /proc/vmstat\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：NUMA可能出现某节点紧张、其他节点空闲；THP启用状态本身不是故障证据，需要结合毛刺期间规整活动、热点栈及应用特征。THP当前模式通常由方括号标出，新内核还可能有按页大小的独立策略。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：检查不合理绑核/绑内存和本地回收策略；THP按数据库/JVM等具体版本的建议及A/B测试选择，不对所有业务统一“always”或“never”。切换策略不代表现有大页立即全部拆分，也不自动持久化。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：比较延迟尾部、CPU、内存占用和吞吐，不能只看平均延迟。\\\\u003ca href=\\\\\\"https://docs.kernel.org/admin-guide/mm/transhuge.html\\\\\\">THP当前接口\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"10-新连接超时分清握手与accept排队\\\\\\">10. 新连接超时：分清握手与accept排队\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先查端口监听与accept队列 → 查半连接 → 对比溢出计数增量 → 确认应用是否及时accept。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看8080监听端口、accept队列和所属进程\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;sport = :8080&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看8080端口仍处于SYN-RECV的连接\\\\u003c/span>\\\\nss -nt state syn-recv \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;( sport = :8080 )&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取监听队列溢出、丢弃及SYN Cookie累计计数\\\\u003c/span>\\\\nnstat -az TcpExtListenOverflows TcpExtListenDrops TcpExtSyncookiesSent\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读：查看accept队列上限、SYN队列限制和SYN Cookie策略\\\\u003c/span>\\\\nsysctl net.core.somaxconn net.ipv4.tcp_max_syn_backlog net.ipv4.tcp_syncookies\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：监听socket的Recv-Q反映等待应用accept的连接，Send-Q对应其backlog上限含义；不能用ESTABLISHED连接的队列含义直接解释。ListenOverflows在事故窗口增加时，进一步查应用是否accept慢、线程池/依赖是否阻塞。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先恢复应用消费连接的能力，控制突发连接并合理复用连接；确需增大backlog时，同时核对应用listen参数与系统上限。SYN压力、accept排队和连接跟踪耗尽是不同问题，不能靠调大一个参数包治。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：以连接成功率、建连耗时、队列趋势和溢出计数增量验收。\\\\u003ca href=\\\\\\"https://docs.kernel.org/networking/ip-sysctl.html\\\\\\">TCP参数说明\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"11-连接已建立但很慢检查重传rtt和收发窗口\\\\\\">11. 连接已建立但很慢：检查重传、RTT和收发窗口\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先看目标连接RTT与队列 → 查重传趋势 → 对照网卡 → 必要时双端抓包。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看指定端口连接的队列、RTT、重传与拥塞窗口\\\\u003c/span>\\\\nss -tin \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;( dport = :8080 or sport = :8080 )&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取整机TCP重传和输出分段累计计数\\\\u003c/span>\\\\nnstat -az TcpRetransSegs TcpOutSegs\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看网卡收发字节、包数、错误与丢弃累计计数\\\\u003c/span>\\\\nip -s \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">link\\\\u003c/span> show dev eth0\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：同一连接重传增加、RTT升高与请求变慢同时出现时，再定位链路；全机TCP重传计数不能直接算作某个服务的重传率。Recv-Q长时间积压要查应用是否及时读，Send-Q积压可能涉及对端接收、链路或发送阻塞。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：两端按同一时间窗口采样，结合抓包分辨发送迟、链路丢、接收不及时。零窗口通常应查接收方应用与内存压力；只换拥塞控制算法不会修复对端不读数据的问题。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：比较目标连接的重传、RTT、队列及业务延迟；不要把调整应用发送超时等同于直接改变TCP内核RTO。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"12-软中断占满单核检查网卡队列和流量分布\\\\\\">12. 软中断占满单核：检查网卡队列和流量分布\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先找高soft的CPU → 看包速率与丢弃 → 比较中断增量 → 核对网卡队列与卸载。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒查看各CPU忙闲、中断和I/O等待，共5次\\\\u003c/span>\\\\nmpstat -P ALL 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒查看网卡吞吐、包速率和错误/丢弃，共5次\\\\u003c/span>\\\\nsar -n DEV,EDEV 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取每核网络收发软中断累计次数\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;NET_RX|NET_TX&#x27;\\\\u003c/span> /proc/softirqs\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取硬中断在各CPU上的累计分布\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/interrupts\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看网卡支持及当前启用的队列数\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ethtool -l eth0\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看网卡协议卸载等功能的启用状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ethtool -k eth0\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看驱动提供的网卡详细统计\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ethtool -S eth0\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：单核soft高且包速率/丢包同时异常，查中断是否集中、是否大量小包。softirqs/interrupts为累计值，要比较增量；ethtool能查看的队列/统计因驱动和虚拟网卡而异。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先查异常流量和硬件RSS/IRQ分配，再评估RPS/RFS与offload。软件分流也消耗CPU，整机已忙时可能进一步压缩业务时间；不要默认把所有卸载特性关闭，或给所有网卡写相同CPU掩码。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：同时看总CPU、单核soft、丢包、吞吐和P99；分布变均匀但吞吐下降不算优化成功。\\\\u003ca href=\\\\\\"https://docs.kernel.org/networking/scaling.html\\\\\\">网络扩展机制\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"13-间歇性卡顿用压力与短时采样留证\\\\\\">13. 间歇性卡顿：用压力与短时采样留证\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先对齐毛刺时间 → 看PSI → 对目标进程短采样 → 按热点进入回收、I/O或调度分支。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取CPU争用造成的停顿指标，需内核支持PSI\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/pressure/cpu\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取内存压力造成的停顿指标\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/pressure/memory\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取I/O压力造成的停顿指标\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/pressure/io\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 对目标进程按49Hz采集调用栈15秒，并保存采样文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf record -F 49 -g -p 24680 -o /tmp/demo-kernel-perf.data -- \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sleep\\\\u003c/span> 15\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取上一步的采样文件，分析热点调用栈\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf report -i /tmp/demo-kernel-perf.data --stdio\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：PSI反映资源争用造成的停顿趋势，不是资源使用率；系统级CPU的full不能照搬内存/I/O的解读。perf只在获得授权、可承受开销时对目标进程短时采样，\\\\u003ccode>-- sleep 15\\\\u003c/code>限定采样时段。\\\\u003ca href=\\\\\\"https://docs.kernel.org/accounting/psi.html\\\\\\">PSI接口\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7等旧内核可能没有 \\\\u003ccode>/proc/pressure/\\\\u003c/code>，这表示该接口不可用，不表示压力为零。此时把上面的三条PSI读取改成以下采样，perf是否可用另行核对：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">vmstat 1 5              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 看运行/阻塞队列、换页与CPU等待，首行常为开机以来平均\\\\u003c/span>\\\\npidstat -r -u -d 1 5    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 看各进程CPU、缺页和I/O，按本机sysstat表头阅读\\\\u003c/span>\\\\niostat -xz 1 5         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 看设备延迟与队列，首份报告常为开机以来累计平均\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这些采样用于关联事故时段，不能换算成PSI百分比；短时毛刺可能被一秒采样平滑，需要结合业务时间线和短时perf采样。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：先把毛刺时间与回收、规整、软中断、业务指标对齐，再由热点栈决定是否深入tracepoint/eBPF。不要一开始就全机长期开高频追踪。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：在同等请求量下，确认停顿与业务尾延迟一起改善；保留内核版本、旧配置、变更项及回退方法。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"14-close_waittime_wait或fin_wait_2很多\\\\\\">14. CLOSE_WAIT、TIME_WAIT或FIN_WAIT_2很多\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先统计状态 → 按业务端口找归属 → 对照连接创建/关闭速率 → 查应用关闭逻辑或端口容量。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：查看整机TCP状态概况\\\\u003c/span>\\\\nss -s\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：查8080服务未及时关闭的连接及其进程，需有查看对应进程的权限\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -ntp state close-wait \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;( sport = :8080 or dport = :8080 )&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：查向8080发起连接的一侧有哪些TIME-WAIT连接\\\\u003c/span>\\\\nss -nt state time-wait \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;( dport = :8080 )&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：检查本端已发送FIN、仍等待对端FIN的连接\\\\u003c/span>\\\\nss -nto state fin-wait-2\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：只读当前临时端口范围、端口保留和关闭相关策略\\\\u003c/span>\\\\nsysctl net.ipv4.ip_local_port_range net.ipv4.ip_local_reserved_ports\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第6步：只读相关TCP策略，先记录现值，不直接调小\\\\u003c/span>\\\\nsysctl net.ipv4.tcp_fin_timeout net.ipv4.tcp_tw_reuse\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：CLOSE_WAIT长期集中在同一PID，优先查该进程是否遗漏关闭连接、异常路径没释放资源；TIME_WAIT随短连接请求量升高，优先查连接复用。TIME_WAIT本身是正常协议保护，不等于泄漏。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>状态\\\\u003c/th>\\\\n\\\\u003cth>接下来查什么\\\\u003c/th>\\\\n\\\\u003cth>容易误用的处理\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>CLOSE_WAIT\\\\u003c/td>\\\\n\\\\u003ctd>被动关闭端的close逻辑、线程阻塞、连接泄漏\\\\u003c/td>\\\\n\\\\u003ctd>调tcp_fin_timeout无法替应用close\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>TIME_WAIT\\\\u003c/td>\\\\n\\\\u003ctd>主动关闭频率、到同一对端的端口容量、连接池\\\\u003c/td>\\\\n\\\\u003ctd>不靠压低数量上限来“清理”连接\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>FIN_WAIT_2\\\\u003c/td>\\\\n\\\\u003ctd>对端是否正常关闭、本端是否仍持有socket\\\\u003c/td>\\\\n\\\\u003ctd>tcp_fin_timeout主要针对孤儿连接，不是所有连接的统一超时\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>SYN_SENT\\\\u003c/td>\\\\n\\\\u003ctd>路由、防火墙、对端监听、握手重试\\\\u003c/td>\\\\n\\\\u003ctd>优先设应用连接期限与故障切换，不盲改整机重试次数\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：修复连接释放和复用；端口确实耗尽时核对源IP、目标IP/端口和保留端口后再评估扩容。TCP连接按地址和端口组合区分，服务端总连接数并非只能有65535个；客户端向不同对端建连也不能一概按全机65535封顶。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：看连接数是否随业务回落、端口分配错误是否消失，以及建连成功率和延迟。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"15-send阻塞或接收丢弃查socket缓冲与总内存\\\\\\">15. send阻塞或接收丢弃：查socket缓冲与总内存\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先查目标连接队列和内存 → 查整机socket占用 → 查限制与应用设置 → 再判断是否需要扩缓冲。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：查看8080连接的队列、TCP内部信息和socket内存\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -tinmp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;( sport = :8080 or dport = :8080 )&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：读取整机socket数量与TCP内存统计\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/net/sockstat\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：只读TCP自动调节范围及接收自动调节开关\\\\u003c/span>\\\\nsysctl net.ipv4.tcp_rmem net.ipv4.tcp_wmem net.ipv4.tcp_moderate_rcvbuf\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：只读应用显式设置socket缓冲时涉及的系统上限\\\\u003c/span>\\\\nsysctl net.core.rmem_max net.core.wmem_max\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：只读全局TCP内存水位，单位为页；不是每连接的字节上限\\\\u003c/span>\\\\nsysctl net.ipv4.tcp_mem\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第6步：确认本机基础页大小，不能一概认为所有架构都是4KB\\\\u003c/span>\\\\ngetconf PAGESIZE\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>skmem\\\\u003c/code>中的 \\\\u003ccode>r/rb\\\\u003c/code> 分别辅助观察已分配接收内存与接收缓冲上限，\\\\u003ccode>w/tb\\\\u003c/code>辅助观察待发送内存与发送缓冲上限；字段按本机ss版本解释。接收队列持续积压时，先查应用不读或处理太慢，扩缓冲只能延后积压暴露。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：区分三种限制：应用显式SO_RCVBUF/SO_SNDBUF、TCP自动调节、整机TCP内存。应用锁定缓冲后，改自动调节参数可能无效；部分socket值包含内核记账开销，不能和有效载荷大小直接相等比较。高带宽长RTT链路再用带宽时延积估算需求，例如100MB/s×0.02s约2MB在途数据，同时预算大量连接的总内存。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：比较目标连接吞吐、发送阻塞、零窗口、丢弃和整机内存；不要只验证“缓冲变大了”。\\\\u003ca href=\\\\\\"https://man7.org/linux/man-pages/man8/ss.8.html\\\\\\">ss内存字段\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"16-virt涨rss不涨最后却申请失败\\\\\\">16. VIRT涨、RSS不涨，最后却申请失败\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：持续观察VSZ/RSS → 查映射数量和资源限制 → 对照映射新增规律 → 追踪申请/释放是否配对。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：每秒观察虚拟内存和常驻内存，采样10次\\\\u003c/span>\\\\npidstat -r -p 24680 1 10\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：统计此进程的VMA数量，每行通常对应一个映射区域\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">wc\\\\u003c/span> -l /proc/24680/maps\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：查看进程真实生效的地址空间、栈和进程等资源限制\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/24680/limits\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：只读全机每进程映射数量上限\\\\u003c/span>\\\\nsysctl vm.max_map_count\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：追踪10秒内的映射、释放、堆扩展和线程创建；会增加目标进程开销\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span> 10s strace -f -tt -T -e trace=mmap,munmap,brk,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">clone\\\\u003c/span> \\\\\\\\\\\\n  -p 24680 -o /tmp/demo-memory-syscalls.log\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：VSZ每隔固定时间增加相近大小，RSS却稳定，新增映射旁有保护页，且clone后缺少对应释放，需查线程栈或自定义映射的生命周期。线程结束不一定代表应用自行分配的栈已释放；但运行库保留栈缓存也可能是正常行为，要看是否有上界。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：核实32位地址空间、RLIMIT_AS、VMA上限及分配失败位置；修复漏掉的munmap或线程资源回收。提高max_map_count只适用于映射数量确实是合理需求的情况，不能代替修复无限增长。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：在相近运行时长下观察VMA、VSZ和未释放分配是否趋稳，并确认线程创建及内存分配错误停止。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"17-内存没用完却出现page-allocation-failure\\\\\\">17. 内存没用完，却出现page allocation failure\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：保留失败日志的order、GFP、调用栈 → 看节点/zone和连续页 → 比较规整与回收 → 按内核版本确认缺陷或驱动需求。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：从最近1小时内核日志中找分配失败及周边上下文\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;1 hour ago&#x27;\\\\u003c/span> --no-pager | \\\\\\\\\\\\n  grep -Ei -A 40 -B 5 \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;page allocation failure|warn_alloc|out of memory&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：查看各节点和zone按阶数分布的空闲块\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/buddyinfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：查看各zone水位和空闲页等信息，输出较长\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/zoneinfo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：读取规整与回收计数，间隔采样后对比增量\\\\u003c/span>\\\\ngrep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;compact_|allocstall|pgscan|pgsteal&#x27;\\\\u003c/span> /proc/vmstat\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：确认故障机器实际内核版本，查询修复时要匹配发行版回移补丁\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -r\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>order=5\\\\u003c/code>表示需要32个基础页连续分配，4KB基础页时为128KB。整机有空闲内存，也可能没有适合的连续块，或当前分配上下文不允许等待、回收、I/O或跨节点。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：将日志、节点水位、buddyinfo和计数交给内核/驱动维护人员核对。能确认版本缺陷时优先使用发行版修复；不根据一条日志就全机清缓存、强制规整或升级未知来源内核。GFP标志及水位逻辑随版本变化，不能把旧版本代码结论套在新内核。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：用相同负载确认分配失败停止，应用错误和尾延迟恢复，不能只看free变大。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"18-重传间歇发生普通采样抓不到连接\\\\\\">18. 重传间歇发生，普通采样抓不到连接\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：先用nstat确认窗口内有重传 → 找到可用重传tracepoint → 短时记录 → 按地址、端口和状态缩小范围 → 必要时双端抓包。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：确认内核是否提供TCP重传事件；无输出时不执行后续记录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf list \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;tcp:tcp_retransmit_skb&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：只记录TCP重传事件10秒；-a覆盖软中断等上下文，不按业务PID误过滤\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf record -a -e tcp:tcp_retransmit_skb \\\\\\\\\\\\n  -o /tmp/demo-retrans.data -- \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sleep\\\\u003c/span> 10\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：展开事件，查看发生重传的地址、端口和连接状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf script -i /tmp/demo-retrans.data\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：事件集中在SYN_SENT，先查握手路径；集中在ESTABLISHED，再查传输、接收窗口和链路。字段随版本变化，不保证都有状态信息。重传可能发生在软中断上下文，事件显示的当前PID未必就是连接的应用PID。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：按四元组与时间关联服务和抓包；该事件主要观察本机重传，不等于能看见对端所有重传。没有事件时用限定目标、时长和包数的tcpdump；不要为了这个工具临时更换生产内核。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：对比同类流量下重传事件增量、连接失败和P99，不将全机累计重传数当作目标业务数据。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"19-已知preadread很慢继续追到内核等待位置\\\\\\">19. 已知pread/read很慢：继续追到内核等待位置\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：strace确认慢调用和线程 → 检查本机可追踪函数 → 用独立trace实例做短采样 → 回到磁盘、页锁或回收对应分支。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>安装trace-cmd，以及使用前的检查\\\\u003c/summary>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian：安装ftrace的命令行工具，会修改已安装软件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install trace-cmd\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># RHEL系：选择此命令安装，不必把两种包管理器命令都执行\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> dnf install trace-cmd\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CentOS 7：改选已有批准仓库中的包，不执行上面的dnf命令\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo yum install trace-cmd\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看工具支持的选项，确认有-B实例和-P线程过滤\\\\u003c/span>\\\\ntrace-cmd record -h\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：内核须支持function_graph及独立实例。旧系统不支持时保留strace、iostat和perf证据，不直接改全局current_tracer覆盖其他采集任务。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：追踪目标进程和线程5秒，记录绝对时间及每个调用耗时\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span> 5s strace -ff -tt -T -p 24680 -o /tmp/demo-read-strace\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：确认pread相关函数在本机可追踪；名称可能与示例不同\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> trace-cmd list -f | grep -E \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;(^|[[:space:]])(ksys_pread64|__x64_sys_pread64)&#x27;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：确认实例名未被其他任务占用；任一位置已存在时改用新的唯一名字\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -d /sys/kernel/tracing/instances/demo-read-24680 /sys/kernel/debug/tracing/instances/demo-read-24680\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：strace显示线程24681的pread64一次耗时80ms，先确认不是工具自身放大的延迟；随后将下面的 \\\\u003ccode>-P 24681\\\\u003c/code> 替换成真正慢的TID，并将函数名替换为上一步确实存在的函数。上面ls提示路径不存在，才表示这两个位置没有同名实例；权限错误不等于不存在。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：在新建独立实例中，只追踪目标线程的pread调用树5秒，写出本次数据\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> trace-cmd record -o /tmp/demo-read.dat -B demo-read-24680 \\\\\\\\\\\\n  -p function_graph -g ksys_pread64 -P 24681 \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sleep\\\\u003c/span> 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：读取调用树，观察页锁、I/O等待或回收等耗时位置\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> trace-cmd report -i /tmp/demo-read.dat\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：调用树沿页锁进入io_schedule，说明线程因等待被调度走，不能据此认定磁盘损坏。继续对齐iostat、Dirty/Writeback、pidstat，检查是否被其他进程写入或页回写阻塞。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：修复对应的竞争或慢存储。追踪会改变时序，优先在可复现环境验证；正常结束后工具会关闭本次启用的追踪并移除新建实例。异常退出需核查本次实例状态，不能一键关闭全机追踪。\\\\u003ca href=\\\\\\"https://www.trace-cmd.org/Documentation/trace-cmd/trace-cmd-record.1.html\\\\\\">trace-cmd记录选项\\\\u003c/a>\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：重新比较真实业务请求与目标调用耗时，同时确认没有遗留本次追踪。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"20-加线程反而变慢查cpu竞争绑核与缓存\\\\\\">20. 加线程反而变慢：查CPU竞争、绑核与缓存\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：确认有效CPU范围 → 看线程调度等待 → 再采样IPC和缓存事件 → 在代码或调度策略上做对照。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：查看CPU、核心、线程和NUMA拓扑，具体缓存共享关系取决于硬件\\\\u003c/span>\\\\nlscpu\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：只读目标进程的CPU亲和性\\\\u003c/span>\\\\ntaskset -pc 24680\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：只读当前调度策略与优先级\\\\u003c/span>\\\\nchrt -p 24680\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第4步：查看各线程CPU占用及等待，共5次\\\\u003c/span>\\\\npidstat -u -w -t -p 24680 1 5\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第5步：统计10秒指令、周期与缓存事件；部分虚拟机/CPU不提供这些事件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> perf \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span> -e cycles,instructions,cache-references,cache-misses \\\\\\\\\\\\n  -p 24680 -- \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sleep\\\\u003c/span> 10\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：线程多、非自愿切换和调度等待高，先查CPU配额、亲和性和过量并发；增加线程后每请求周期增多、缓存事件异常，再考虑共享热点、数据局部性或伪共享。cache-misses高本身不能证明伪共享，必要时在支持的硬件上进一步用perf c2c。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：减少共享计数器争用，使用分片/批量聚合，避免无效轮询；确有伪共享再改数据布局。绑核可能把任务挤在少数CPU上，实时调度也可能饿死其他工作，不作为通用提速开关。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：对比同等吞吐下每请求CPU成本、调度等待和P99；检查其他服务是否受到影响。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"21-故障过去了如何追查当时的回收或卡顿\\\\\\">21. 故障过去了，如何追查当时的回收或卡顿\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：确定日期和时间窗口 → 找到事先采集的数据 → 对齐业务延迟 → 判断相关性 → 下次补采最缺的证据。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第1步：查看两种常见目录，找故障日期对应的sar二进制文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -lh /var/log/sa /var/log/sysstat\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第2步：示例读取sa03文件的22:30至22:45分页与回收记录，目录和文件名按实际替换\\\\u003c/span>\\\\nsar -B -f /var/log/sa/sa03 -s 22:30:00 -e 22:45:00\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 第3步：读取同一文件、同一时间段的内存指标\\\\u003c/span>\\\\nsar -r -f /var/log/sa/sa03 -s 22:30:00 -e 22:45:00\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：业务P99升高的多个时间点与直接回收同时出现，可以作为进一步采样的方向；几条历史曲线吻合仍不等于已证明因果。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>处理\\\\u003c/strong>：没有事先采集就无法靠现在的sar还原过去。为反复发生的问题补充回收/规整/重传计数、PSI及业务延迟的定时采样，统一时区并设保留期；不把瞬时累计计数当作昨日现场。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>复查\\\\u003c/strong>：下一次毛刺发生时能同时找到业务、进程与内核层的证据，采集本身没有明显干扰。\\\\u003c/p>\\\\n\\\\u003cp>相关内容：\\\\u003ca href=\\\\\\"linux-performance-troubleshooting.html\\\\\\">Linux性能瓶颈排查与优化\\\\u003c/a>、\\\\u003ca href=\\\\\\"linux-server-operations-commands.html\\\\\\">服务器常用命令\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"1. 先决定查哪条线\\",\\"level\\":2,\\"id\\":\\"1-先决定查哪条线\\"},{\\"title\\":\\"2. free很少，是否真的缺内存\\",\\"level\\":2,\\"id\\":\\"2-free很少是否真的缺内存\\"},{\\"title\\":\\"3. load飙高、延迟变大：检查回收和脏页\\",\\"level\\":2,\\"id\\":\\"3-load飙高延迟变大检查回收和脏页\\"},{\\"title\\":\\"4. 清过缓存后更慢：检查热点数据反复读盘\\",\\"level\\":2,\\"id\\":\\"4-清过缓存后更慢检查热点数据反复读盘\\"},{\\"title\\":\\"5. 进程RSS持续涨：区分堆、映射与共享页\\",\\"level\\":2,\\"id\\":\\"5-进程rss持续涨区分堆映射与共享页\\"},{\\"title\\":\\"6. RSS不高、Shmem很大：查tmpfs与共享内存\\",\\"level\\":2,\\"id\\":\\"6-rss不高shmem很大查tmpfs与共享内存\\"},{\\"title\\":\\"7. 内核内存持续增长：查Slab、驱动与分配点\\",\\"level\\":2,\\"id\\":\\"7-内核内存持续增长查slab驱动与分配点\\"},{\\"title\\":\\"8. 服务被杀、容器OOM：先确认边界\\",\\"level\\":2,\\"id\\":\\"8-服务被杀容器oom先确认边界\\"},{\\"title\\":\\"9. 有空闲内存还卡顿：查NUMA和透明大页\\",\\"level\\":2,\\"id\\":\\"9-有空闲内存还卡顿查numa和透明大页\\"},{\\"title\\":\\"10. 新连接超时：分清握手与accept排队\\",\\"level\\":2,\\"id\\":\\"10-新连接超时分清握手与accept排队\\"},{\\"title\\":\\"11. 连接已建立但很慢：检查重传、RTT和收发窗口\\",\\"level\\":2,\\"id\\":\\"11-连接已建立但很慢检查重传rtt和收发窗口\\"},{\\"title\\":\\"12. 软中断占满单核：检查网卡队列和流量分布\\",\\"level\\":2,\\"id\\":\\"12-软中断占满单核检查网卡队列和流量分布\\"},{\\"title\\":\\"13. 间歇性卡顿：用压力与短时采样留证\\",\\"level\\":2,\\"id\\":\\"13-间歇性卡顿用压力与短时采样留证\\"},{\\"title\\":\\"14. CLOSE_WAIT、TIME_WAIT或FIN_WAIT_2很多\\",\\"level\\":2,\\"id\\":\\"14-close_waittime_wait或fin_wait_2很多\\"},{\\"title\\":\\"15. send阻塞或接收丢弃：查socket缓冲与总内存\\",\\"level\\":2,\\"id\\":\\"15-send阻塞或接收丢弃查socket缓冲与总内存\\"},{\\"title\\":\\"16. VIRT涨、RSS不涨，最后却申请失败\\",\\"level\\":2,\\"id\\":\\"16-virt涨rss不涨最后却申请失败\\"},{\\"title\\":\\"17. 内存没用完，却出现page allocation failure\\",\\"level\\":2,\\"id\\":\\"17-内存没用完却出现page-allocation-failure\\"},{\\"title\\":\\"18. 重传间歇发生，普通采样抓不到连接\\",\\"level\\":2,\\"id\\":\\"18-重传间歇发生普通采样抓不到连接\\"},{\\"title\\":\\"19. 已知pread/read很慢：继续追到内核等待位置\\",\\"level\\":2,\\"id\\":\\"19-已知preadread很慢继续追到内核等待位置\\"},{\\"title\\":\\"20. 加线程反而变慢：查CPU竞争、绑核与缓存\\",\\"level\\":2,\\"id\\":\\"20-加线程反而变慢查cpu竞争绑核与缓存\\"},{\\"title\\":\\"21. 故障过去了，如何追查当时的回收或卡顿\\",\\"level\\":2,\\"id\\":\\"21-故障过去了如何追查当时的回收或卡顿\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/linux-kernel-troubleshooting.md","filePath":"articles/linux-kernel-troubleshooting.md"}'),u={name:"articles/linux-kernel-troubleshooting.md"};function a(t,e,p,l,o,r){return s(),n("div")}const d=c(u,[["render",a]]);export{m as __pageData,d as default};
